import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.Di-jvWLj.js";const h=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1792480428000}'),o={name:"guide/index.md"};function r(d,e,i,c,p,l){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>This guide describes <code>@chamberu/core</code> as it is built today. Every sample on these pages type-checks against the current source.</p><h2 id="the-concepts" tabindex="-1">The concepts <a class="header-anchor" href="#the-concepts" aria-label="Permalink to &quot;The concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>In core</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td><code>defineAgent()</code></td><td>A model, instructions, triggers, a tool factory, a budget, approvals and state</td></tr><tr><td><strong>Trigger</strong></td><td><code>cron()</code>, <code>http()</code>, <code>webhook()</code></td><td>How a run can start. Normalized into a <code>TriggerEnvelope</code> at intake</td></tr><tr><td><strong>Run</strong></td><td><code>Run</code></td><td>One execution of an agent for one envelope, with a status, usage and output</td></tr><tr><td><strong>Step</strong></td><td><code>Step</code></td><td>An <code>llm</code>, <code>tool</code> or <code>wait</code> record, appended as the run progresses</td></tr><tr><td><strong>Checkpoint</strong></td><td><code>Checkpoint</code></td><td>The message history after a step; a resumed run continues from the latest one</td></tr><tr><td><strong>Tool</strong></td><td>AI SDK <code>tool()</code>, <code>defineEffectTool()</code></td><td>What the model can call. Effect tools apply at most once per effect key</td></tr><tr><td><strong>State</strong></td><td><code>AgentState</code></td><td>Per-agent key-value data and typed collections that outlive runs</td></tr><tr><td><strong>Notifier</strong></td><td><code>Notifier</code></td><td>Delivers approval requests and other messages to the owner</td></tr><tr><td><strong>Store</strong></td><td><code>Store</code></td><td>Runs, steps, checkpoints, keys, locks, effects and state. Pluggable</td></tr></tbody></table><p>The <strong>App</strong> and <strong>Workspace</strong> concepts (an app with HTTP, scheduler and UI, and sandboxed workspaces for coding) belong to <a href="/roadmap">planned packages</a>.</p><h2 id="the-engine-in-one-picture" tabindex="-1">The engine in one picture <a class="header-anchor" href="#the-engine-in-one-picture" aria-label="Permalink to &quot;The engine in one picture&quot;">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span>             dispatch(envelope)</span></span>
<span class="line"><span>                    |</span></span>
<span class="line"><span>        idempotency key seen? ----yes----&gt; existing run id</span></span>
<span class="line"><span>                    | no</span></span>
<span class="line"><span>                    v</span></span>
<span class="line"><span>               [ queued ] &lt;--------------------------------+</span></span>
<span class="line"><span>                    | slot free, key free, claim taken     |</span></span>
<span class="line"><span>                    v                                      |</span></span>
<span class="line"><span>               [ running ] --- step --&gt; checkpoint         |</span></span>
<span class="line"><span>                    |                                      |</span></span>
<span class="line"><span>   +----------------+-----------------+-----------------+  |</span></span>
<span class="line"><span>   |                |                 |                 |  |</span></span>
<span class="line"><span>completed         failed          cancelled        waiting -- resume / timeout</span></span>
<span class="line"><span>                                                    interrupted -- recover</span></span></code></pre></div><p>See <a href="/guide/run-lifecycle">Run Lifecycle</a> for every transition.</p><h2 id="reading-order" tabindex="-1">Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to &quot;Reading order&quot;">​</a></h2><ol><li><a href="/guide/agents">Agents</a> and <a href="/guide/triggers">Triggers &amp; the Envelope</a></li><li><a href="/guide/run-lifecycle">Run Lifecycle</a> and <a href="/guide/execution">Execution &amp; Checkpoints</a></li><li><a href="/guide/budgets">Budgets</a>, <a href="/guide/tools">Tools</a>, <a href="/guide/effect-tools">Effect Tools</a>, <a href="/guide/approvals">Approvals</a>, <a href="/guide/state">State</a></li><li><a href="/guide/concurrency">Concurrency</a>, <a href="/guide/recovery">Cancel, Drain &amp; Recovery</a>, <a href="/guide/notifiers">Notifiers</a>, <a href="/guide/errors">Errors</a></li></ol>`,10)])])}const u=t(o,[["render",r]]);export{h as __pageData,u as default};
